export type FillMode = 'fill' | 'fit';
export type AspectRatio = '9:16' | '16:9' | '1:1';
export type DurationMode = 'full' | 'custom';
export type TextPosition =
  | 'top-left' | 'top-center' | 'top-right'
  | 'center-left' | 'center' | 'center-right'
  | 'bottom-left' | 'bottom-center' | 'bottom-right';

export interface VideoMetadata {
  duration: number;
  video?: {
    codec: string;
    width: number;
    height: number;
    frameRate: number;
    rotation: number;
  };
  audio?: {
    codec: string;
    sampleRate: number;
    channels: number;
  };
}

export interface VideoTrack {
  type: 'video';
  id: string;
  name: string;
  /** Blob URL created via URL.createObjectURL — must be revoked when no longer used. */
  objectUrl: string;
  startTime: number;
  duration: number;
  fillMode: FillMode;
  bgColor: string;
  blob?: Blob;
  metadata?: VideoMetadata;
  metaError?: string;
}

export interface TextItem {
  type: 'text';
  id: string;
  text: string;
  fontFamily: string;
  fontWeight: string;
  fontSize: number;
  color: string;
  position: TextPosition;
  duration: number;
}

export type TimelineItem = VideoTrack | TextItem;

export interface ClipInput {
  blob: Blob;
  startTime: number;
  duration: number;
  fillMode: FillMode;
  /** Optional cached metadata to avoid re-extraction during export. */
  metadata?: VideoMetadata;
}

import React, { useState, useRef, useEffect } from 'react';
import {
  ChevronDown,
  ArrowUpLeft, ArrowUp, ArrowUpRight,
  ArrowLeft, Crosshair, ArrowRight,
  ArrowDownLeft, ArrowDown, ArrowDownRight,
} from 'lucide-react';
import { TextPosition } from '../types';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      setIsOpen(false);
    };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none bg-transparent">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <ChevronDown size={16} className={`text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-[100] top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const RangeSlider: React.FC<{
  label: string; 
  value: number; 
  min: number; 
  max: number;
  step?: number; 
  formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);

export const SegmentedToggle: React.FC<{
  value: string; 
  items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-3 py-2 text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

/** 3x3 Position Grid — matching the screenshot reference */
export const PositionGrid: React.FC<{
  value: TextPosition;
  onChange: (pos: TextPosition) => void;
}> = ({ value, onChange }) => {
  const grid: { pos: TextPosition; icon: React.ReactNode }[][] = [
    [
      { pos: 'top-left', icon: <ArrowUpLeft size={16} /> },
      { pos: 'top-center', icon: <ArrowUp size={16} /> },
      { pos: 'top-right', icon: <ArrowUpRight size={16} /> },
    ],
    [
      { pos: 'center-left', icon: <ArrowLeft size={16} /> },
      { pos: 'center', icon: <Crosshair size={16} /> },
      { pos: 'center-right', icon: <ArrowRight size={16} /> },
    ],
    [
      { pos: 'bottom-left', icon: <ArrowDownLeft size={16} /> },
      { pos: 'bottom-center', icon: <ArrowDown size={16} /> },
      { pos: 'bottom-right', icon: <ArrowDownRight size={16} /> },
    ],
  ];

  return (
    <div className="border border-[#595959] rounded-xl overflow-hidden">
      {grid.map((row, ri) => (
        <div key={ri} className="flex">
          {row.map((cell, ci) => (
            <button
              key={cell.pos}
              type="button"
              onClick={() => onChange(cell.pos)}
              className={`flex-1 flex items-center justify-center h-10 transition-all
                ${value === cell.pos ? 'bg-[#969696]/40 text-white' : 'text-[rgba(218,220,224,0.5)] hover:bg-white/5 hover:text-white'}
                ${ri < 2 ? 'border-b border-[#595959]' : ''}
                ${ci < 2 ? 'border-r border-[#595959]' : ''}`}
            >
              {cell.icon}
            </button>
          ))}
        </div>
      ))}
    </div>
  );
};

/** Color Input — hex field with circular swatch + native color picker */
export const ColorInput: React.FC<{
  label: string;
  value: string;
  onChange: (hex: string) => void;
}> = ({ label, value, onChange }) => {
  const pickerRef = useRef<HTMLInputElement>(null);

  return (
    <div className="flex flex-col gap-1.5 w-full">
      <div className="px-2">
        <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      </div>
      <div
        className="flex items-center gap-2.5 border border-[#595959] rounded-xl px-2.5 py-2 cursor-pointer hover:border-[#7a7a7a] transition-colors"
        onClick={() => pickerRef.current?.click()}
      >
        <div
          className="w-6 h-6 rounded-full border border-white/20 shrink-0"
          style={{ backgroundColor: value }}
        />
        <span className="text-[11px] font-medium text-white tracking-[0.1px] uppercase">{value}</span>
        <input
          ref={pickerRef}
          type="color"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute opacity-0 w-0 h-0 pointer-events-none"
        />
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
