const GOOGLE_FONTS = [
  'Google Sans',
  'Inter',
  'Roboto',
  'Poppins',
  'Montserrat',
  'Playfair Display',
  'Space Grotesk',
  'DM Sans',
  'Outfit',
  'Bebas Neue',
