const FONT_WEIGHTS = [
  { value: '400', label: 'Regular' },
  { value: '500', label: 'Medium' },
  { value: '600', label: 'SemiBold' },
  { value: '700', label: 'Bold' },
];

interface VideoEditorProps {
  onLog: (msg: string, type?: 'info' | 'ffmpeg' | 'error') => void;
}

function checkClipCompatibility(
  meta: VideoMetadata | undefined,
  reference: VideoMetadata | undefined
): { ok: boolean; message: string } {
  if (!reference || !meta) return { ok: true, message: '' };
  const errors: string[] = [];
  if (meta.video?.width !== reference.video?.width || meta.video?.height !== reference.video?.height) {
    errors.push('Dimensions differ');
  }
  if (meta.video?.codec !== reference.video?.codec) {
    errors.push('Codec differs');
  }
  if (meta.video && reference.video) {
    const fpsDelta = Math.abs((meta.video.frameRate || 0) - (reference.video.frameRate || 0));
    if (fpsDelta > 1) errors.push('Frame rate differs');
  }
  if (!!meta.audio !== !!reference.audio) {
    errors.push('Audio differs');
  }
  if (meta.audio && reference.audio) {
    if (meta.audio.sampleRate !== reference.audio.sampleRate) errors.push('Sample rate differs');
    if (meta.audio.channels !== reference.audio.channels) errors.push('Channels differ');
    if (meta.audio.codec !== reference.audio.codec) errors.push('Audio codec differs');
  }
  return { ok: errors.length === 0, message: errors.join(', ') };
}

function createDefaultTextItem(duration: number): TextItem {
  return {
    type: 'text',
    id: crypto.randomUUID(),
    text: 'Chapter Name',
    fontFamily: 'Google Sans',
    fontWeight: '500',
    fontSize: 84,
    color: '#ffffff',
    position: 'center',
    duration,
  };
}

const positionClasses: Record<TextPosition, string> = {
  'top-left': 'items-start justify-start',
  'top-center': 'items-start justify-center',
  'top-right': 'items-start justify-end',
  'center-left': 'items-center justify-start',
  'center': 'items-center justify-center',
  'center-right': 'items-center justify-end',
  'bottom-left': 'items-end justify-start',
  'bottom-center': 'items-end justify-center',
  'bottom-right': 'items-end justify-end',
};

function ensureFontLoaded(fontFamily: string) {
  const id = `font-${fontFamily.replace(/\s+/g, '-').toLowerCase()}`;
  if (document.getElementById(id)) return;
  const link = document.createElement('link');
  link.id = id;
  link.rel = 'stylesheet';
  link.href = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(fontFamily)}:wght@400;500;600;700&display=swap`;
  document.head.appendChild(link);
}

export const VideoEditor: React.FC<VideoEditorProps> = ({ onLog }) => {
  const [items, setItems] = useState<TimelineItem[]>([]);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [customDuration, setCustomDuration] = useState(0.4);
  const [durationMode, setDurationMode] = useState<DurationMode>('custom');
  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
  const [globalFillMode, setGlobalFillMode] = useState<FillMode>('fit');
  const [isRendering, setIsRendering] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [sequenceIndex, setSequenceIndex] = useState(0);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [activeInsertZone, setActiveInsertZone] = useState<number>(-1);
  const [exportResult, setExportResult] = useState<{ url: string; name: string; mediaId?: string } | null>(null);
  const [isDraggingFiles, setIsDraggingFiles] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const textTimerRef = useRef<number | null>(null);
  const itemsRef = useRef<TimelineItem[]>([]);
  const exportResultRef = useRef<{ url: string; name: string; mediaId?: string } | null>(null);

  const previewIndex = isPlaying ? sequenceIndex : (selectedIndex ?? 0);
  const previewItem = items[previewIndex] || null;

  const videoTracks = items.filter((i): i is VideoTrack => i.type === 'video');
  const hasTextItems = items.some(i => i.type === 'text');

  const shortestAssetDuration = useMemo(() => {
    const durs = items
      .filter((i): i is VideoTrack => i.type === 'video' && !!i.metadata?.duration)
      .map(i => i.metadata!.duration);
    return durs.length ? Math.min(...durs) : null;
  }, [items]);

  const effectiveMaxDuration = shortestAssetDuration
    ? Math.max(0.1, Math.floor(shortestAssetDuration * 10) / 10)
    : 5.0;

  const referenceMetadata = videoTracks[0]?.metadata;
  const allCompatible = videoTracks.every(
    (t) => !t.metadata || checkClipCompatibility(t.metadata, referenceMetadata).ok
  );
  const needsReencode = !allCompatible || globalFillMode !== 'fit' || hasTextItems;

  useEffect(() => {
    if (!isPlaying || items.length === 0) return;
    if (previewItem?.type !== 'text') return;

    const dur = Math.max(0, previewItem.duration) * 1000;
    const id = window.setTimeout(() => {
      setSequenceIndex((prev) => {
        const next = prev + 1;
        if (next >= items.length) {
          setIsPlaying(false);
          return 0;
        }
        return next;
      });
    }, dur);
    textTimerRef.current = id;
    return () => {
      clearTimeout(id);
      if (textTimerRef.current === id) textTimerRef.current = null;
    };
  }, [isPlaying, previewItem, items.length]);

  useEffect(() => {
    if (!isPlaying || previewItem?.type !== 'video') return;
    const video = videoRef.current;
    if (!video) return;

    const advance = () => {
      setSequenceIndex((prev) => {
        const next = prev + 1;
        if (next >= items.length) {
          setIsPlaying(false);
          video.pause();
          return 0;
        }
        return next;
      });
    };

    const onTimeUpdate = () => {
      const elapsed = video.currentTime - previewItem.startTime;
      if (elapsed >= previewItem.duration) advance();
    };

    video.addEventListener('timeupdate', onTimeUpdate);
    video.addEventListener('ended', advance);
    return () => {
      video.removeEventListener('timeupdate', onTimeUpdate);
      video.removeEventListener('ended', advance);
    };
  }, [isPlaying, previewItem, items.length]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (previewItem?.type !== 'video') {
      video.pause();
      return;
    }
    try {
      video.currentTime = previewItem.startTime;
    } catch {
      const onLoaded = () => {
        try { video.currentTime = previewItem.startTime; } catch {}
        video.removeEventListener('loadedmetadata', onLoaded);
      };
      video.addEventListener('loadedmetadata', onLoaded);
    }
  }, [previewItem?.id, previewItem?.type]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    if (previewItem?.type !== 'video') {
      video.pause();
      return;
    }
    if (isPlaying) {
      const playPromise = video.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          setIsPlaying(false);
        });
      }
    } else {
      video.pause();
    }
  }, [isPlaying, previewItem?.id, previewItem?.type]);

  useEffect(() => {
    return () => {
      for (const item of itemsRef.current) {
        if (item.type === 'video' && item.objectUrl) {
          URL.revokeObjectURL(item.objectUrl);
        }
      }
      if (exportResultRef.current) {
        URL.revokeObjectURL(exportResultRef.current.url);
      }
      if (textTimerRef.current) clearTimeout(textTimerRef.current);
    };
  }, []);

  useEffect(() => { itemsRef.current = items; }, [items]);
  useEffect(() => { exportResultRef.current = exportResult; }, [exportResult]);

  useEffect(() => {
    if (sequenceIndex >= items.length) {
      setIsPlaying(false);
      setSequenceIndex(0);
    }
  }, [items.length, sequenceIndex]);

  const addTracksToTimeline = useCallback((newTracks: VideoTrack[]) => {
    let assignedSelection = false;
    setItems((prev) => {
      if (selectedIndex === null && !assignedSelection) {
        assignedSelection = true;
        queueMicrotask(() => setSelectedIndex(prev.length));
      }
      return [...prev, ...newTracks];
    });

    newTracks.forEach(async (track) => {
      try {
        const metadata = await extractMetadata(track.blob!);
        setItems((prev) => {
          const otherDurs = prev
            .filter((t): t is VideoTrack => t.type === 'video' && !!t.metadata?.duration && t.id !== track.id)
            .map(t => t.metadata!.duration);
          const newShortest = Math.min(metadata.duration, ...(otherDurs.length ? otherDurs : [Infinity]));
          const newMax = Math.max(0.1, Math.floor(newShortest * 10) / 10);

          setCustomDuration((cur) => (cur > newMax ? newMax : cur));

          return prev.map((t) => {
            if (t.id === track.id) {
              return {
                ...t,
                metadata,
                duration: durationMode === 'full' ? metadata.duration : Math.min(t.duration, newMax),
              };
            }
            if (t.type === 'video' && t.duration > newMax && durationMode === 'custom') {
              return { ...t, duration: newMax };
            }
            return t;
          });
        });
        onLog(`Probed ${track.name}: ${metadata.video?.width}x${metadata.video?.height}`, 'info');
      } catch (err: any) {
        setItems((prev) =>
          prev.map((t) =>
            t.id === track.id ? { ...t, metaError: err.message || 'Failed to read metadata' } : t
          )
        );
        onLog(`Metadata error for ${track.name}: ${err.message}`, 'error');
      }
    });
  }, [durationMode, onLog, selectedIndex]);

  const handleImportFromGallery = async () => {
    try {
      const selections = await Flow.media.selectMultiple({ filter: 'video' });
      if (selections.length === 0) return;

      onLog(`Importing ${selections.length} clips from gallery...`, 'info');

      const newTracks: VideoTrack[] = selections.map(item => {
        const bytes = Uint8Array.from(atob(item.base64), c => c.charCodeAt(0));
        const blob = new Blob([bytes], { type: item.mimeType });

        return {
          type: 'video' as const,
          id: crypto.randomUUID(),
          name: item.name || 'Gallery Clip',
          objectUrl: URL.createObjectURL(blob),
          startTime: 0,
          duration: durationMode === 'custom' ? customDuration : 0.5,
          fillMode: globalFillMode,
          bgColor: '#000000',
          blob,
        };
      });

      addTracksToTimeline(newTracks);
    } catch (err: any) {
      onLog(`Import failed: ${err.message}`, 'error');
    }
  };

  const handleUploadFiles = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.accept = 'video/*';
    input.onchange = (e) => {
      const target = e.target as HTMLInputElement;
      if (!target.files || target.files.length === 0) return;

      const files = Array.from(target.files);
      const newTracks: VideoTrack[] = files.map(file => ({
        type: 'video' as const,
        id: crypto.randomUUID(),
        name: file.name || 'Upload Clip',
        objectUrl: URL.createObjectURL(file),
        startTime: 0,
        duration: durationMode === 'custom' ? customDuration : 0.5,
        fillMode: globalFillMode,
        bgColor: '#000000',
        blob: file,
      }));

      addTracksToTimeline(newTracks);
    };
    input.click();
  };

  const insertTextAt = (index: number) => {
    const textItem = createDefaultTextItem(customDuration);
    setItems((prev) => {
      const next = [...prev];
      next.splice(index, 0, textItem);
      return next;
    });
    setSelectedIndex(index);
    onLog('Added text chapter card.', 'info');
  };

  const handleDurationModeChange = (mode: string) => {
    const newMode = mode as DurationMode;
    setDurationMode(newMode);
    setItems((prev) => prev.map((item) => {
      if (item.type === 'video') {
        return {
          ...item,
          duration: newMode === 'full' ? (item.metadata?.duration ?? item.duration) : customDuration
        };
      }
      return item;
    }));
    onLog(`Switched duration mode to: ${newMode}`, 'info');
  };

  const updateGlobalDuration = (val: number) => {
    const newVal = Math.max(0.1, Math.min(effectiveMaxDuration, parseFloat(val.toFixed(1))));
    setCustomDuration(newVal);
    if (durationMode === 'custom') {
      setItems((prev) => prev.map((t) => ({ ...t, duration: newVal })));
    } else {
      setItems((prev) => prev.map((t) => t.type === 'text' ? { ...t, duration: newVal } : t));
    }
  };

  const shuffleItems = () => {
    setIsPlaying(false);
    setItems((prev) => {
      const arr = [...prev];
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      return arr;
    });
    onLog('Shuffled sequence', 'info');
    setSequenceIndex(0);
  };

  const updateItem = (index: number, updates: Partial<TimelineItem>) => {
    setItems((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], ...updates } as TimelineItem;
      return next;
    });
  };

  const removeItem = (index: number) => {
    const removed = items[index];
    if (removed?.type === 'video' && removed.objectUrl) {
      URL.revokeObjectURL(removed.objectUrl);
    }
    if (isPlaying && sequenceIndex === index) {
      setIsPlaying(false);
      setSequenceIndex(0);
    }
    if (selectedIndex === index) {
      setSelectedIndex(items.length <= 1 ? null : Math.max(0, index - 1));
    } else if (selectedIndex !== null && index < selectedIndex) {
      setSelectedIndex(prev => (prev !== null ? prev - 1 : null));
    }
    setItems((prev) => prev.filter((_, i) => i !== index));
  };

  const handleDragStart = (index: number) => setDraggedIndex(index);

  const insertZoneFromTile = (tileIndex: number): number => {
    if (draggedIndex === null) return -1;
    if (tileIndex === draggedIndex) return -1;
    return draggedIndex < tileIndex ? tileIndex + 1 : tileIndex;
  };

  const isNoOpZone = (zone: number): boolean => {
    if (draggedIndex === null) return true;
    return zone === draggedIndex || zone === draggedIndex + 1;
  };

  const handleDragOverTile = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || index === draggedIndex) return;
    const zone = insertZoneFromTile(index);
    if (activeInsertZone !== zone) setActiveInsertZone(zone);
  };

  const handleDragOverInsertZone = (e: React.DragEvent, zoneIndex: number) => {
    e.preventDefault();
    if (draggedIndex === null) return;
    if (isNoOpZone(zoneIndex)) {
      if (activeInsertZone !== -1) setActiveInsertZone(-1);
      return;
    }
    if (activeInsertZone !== zoneIndex) setActiveInsertZone(zoneIndex);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
    setActiveInsertZone(-1);
  };

  const handleDropAtInsertZone = (zoneIndex: number) => {
    if (draggedIndex === null) { handleDragEnd(); return; }
    if (isNoOpZone(zoneIndex)) { handleDragEnd(); return; }
    if (isPlaying) setIsPlaying(false);
    const reordered = [...items];
    const [moved] = reordered.splice(draggedIndex, 1);
    const targetPos = draggedIndex < zoneIndex ? zoneIndex - 1 : zoneIndex;
    reordered.splice(targetPos, 0, moved);
    setItems(reordered);
    setSelectedIndex(targetPos);
    handleDragEnd();
  };

  const handleDrop = (index: number) => {
    if (draggedIndex === null) { handleDragEnd(); return; }
    if (index === draggedIndex) { handleDragEnd(); return; }
    handleDropAtInsertZone(insertZoneFromTile(index));
  };

  const handleRender = async () => {
    if (items.length === 0) return;
    const missingBlobs = videoTracks.filter((t) => !t.blob);
    if (missingBlobs.length > 0) {
      onLog('Some clips are still loading...', 'error');
      return;
    }

    setIsRendering(true);
    onLog('Starting export & save to gallery...', 'info');

    try {
      const [targetW, targetH] =
        aspectRatio === '9:16' ? [1080, 1920] :
        aspectRatio === '16:9' ? [1920, 1080] :
        [1080, 1080];

      // Anchor FPS from the first actual video track in the sequence
      const targetFPS = videoTracks[0]?.metadata?.video?.frameRate || 30;

      const clips: ClipInput[] = [];
      for (const item of items) {
        if (item.type === 'video') {
          clips.push({
            blob: item.blob!,
            startTime: item.startTime,
            duration: item.duration,
            fillMode: globalFillMode,
            metadata: item.metadata,
          });
        } else {
          onLog(`Rendering text card at ${targetFPS} FPS...`, 'info');
          const textBlob = await generateTextBlob(item, targetW, targetH, targetFPS);
          clips.push({
            blob: textBlob,
            startTime: 0,
            duration: item.duration,
            fillMode: 'fit',
          });
        }
      }

      let blob: Blob;
      if (needsReencode) {
        onLog(`Re-encoding stringout at ${targetFPS} FPS...`, 'info');
        blob = await reencodeVideos(clips, targetW, targetH, targetFPS, (p) => {
          onLog(`Progress: ${Math.round(p * 100)}%`, 'info');
        });
      } else {
        onLog(`Stitching clips...`, 'info');
        blob = await concatenateVideos(clips, (p) => {
          onLog(`Progress: ${Math.round(p * 100)}%`, 'info');
        });
      }

      const videoName = `Stringout_${Date.now()}.mp4`;

      const reader = new FileReader();
      const saveToFlowPromise = new Promise<string>((resolve, reject) => {
        reader.onloadend = async () => {
          try {
            const base64 = (reader.result as string).split(',')[1];
            const saved = await Flow.save({
              base64,
              mimeType: 'video/mp4',
              name: videoName,
            });
            resolve(saved.mediaId);
          } catch (e) {
            reject(e);
          }
        };
        reader.onerror = () => reject(new Error("Failed to read blob"));
        reader.readAsDataURL(blob);
      });

      const mediaId = await saveToFlowPromise;
      const url = URL.createObjectURL(blob);

      setExportResult((prev) => {
        if (prev) URL.revokeObjectURL(prev.url);
        return { url, name: videoName, mediaId };
      });

      onLog('Export successful. Saved to Gallery.', 'info');
    } catch (err: any) {
      onLog(`Export error: ${err.message || err}`, 'error');
    } finally {
      setIsRendering(false);
    }
  };

  const closeExportModal = useCallback(() => {
    setExportResult((prev) => {
      if (prev) URL.revokeObjectURL(prev.url);
      return null;
    });
  }, []);

  const selectedItem = selectedIndex !== null ? items[selectedIndex] : null;

  const aspectStyles = {
    '9:16': 'aspect-[9/16] h-[calc(100vh-320px)] max-h-[700px]',
    '16:9': 'aspect-[16/9] w-[calc(100%-48px)] max-w-[900px]',
    '1:1': 'aspect-square h-[calc(100vh-320px)] max-h-[600px]',
  };

  const renderTextPreview = (item: TextItem) => {
    const alignClass = item.position.includes('left') ? 'text-left' : item.position.includes('right') ? 'text-right' : 'text-center';
    return (
      <div className={`w-full h-full flex ${positionClasses[item.position]} p-8 relative bg-zinc-950`}>
        <p
          className={`relative z-10 ${alignClass} max-w-full break-words px-4`}
          style={{
            fontFamily: `"${item.fontFamily}", sans-serif`,
            fontWeight: Number(item.fontWeight),
            fontSize: `${item.fontSize * 0.4}px`,
            lineHeight: 1.2,
            color: item.color,
          }}
        >
          {item.text || 'Type something...'}
        </p>
      </div>
    );
  };

  return (
    <div className="flex h-full w-full bg-[#0e0e0e] overflow-hidden">
      {exportResult && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-[#1a1a1a] border border-[#595959] rounded-2xl max-w-xl w-full overflow-hidden shadow-2xl flex flex-col">
            <div className="p-4 border-b border-[#595959] flex items-center justify-between bg-black/20">
              <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">Saved to Gallery</span>
              <button onClick={closeExportModal} className="p-2 -mr-2 text-zinc-500 hover:text-white transition-colors">
                <X size={20} />
              </button>
            </div>
            <div className="p-8 flex items-center justify-center bg-black/40">
              <div className={`shadow-2xl rounded-xl overflow-hidden border border-[#595959] ${aspectRatio === '9:16' ? 'h-[300px] aspect-[9/16]' : aspectRatio === '16:9' ? 'w-full aspect-[16/9]' : 'h-[300px] aspect-square'}`}>
                <video src={exportResult.url} controls className="w-full h-full" autoPlay loop />
              </div>
            </div>
            <div className="p-4 flex gap-1.5">
              <PillButton variant="solid" onClick={closeExportModal}>Done</PillButton>
            </div>
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col min-h-0 min-w-0 relative">
        <div className="flex-1 flex flex-col items-center justify-center p-4 md:p-8 bg-black/40 relative">
          <div className={`bg-black shadow-[0_0_80px_rgba(0,0,0,0.8)] border-[1px] border-white/5 relative overflow-hidden transition-all duration-500 rounded-3xl ${aspectStyles[aspectRatio]}`}>
            {previewItem?.type === 'video' ? (
              <video ref={videoRef} src={previewItem.objectUrl} className={`w-full h-full ${globalFillMode === 'fill' ? 'object-cover' : 'object-contain'}`} muted />
            ) : previewItem?.type === 'text' ? (
              renderTextPreview(previewItem)
            ) : (
              <div
                onClick={handleImportFromGallery}
                onDragOver={(e) => { e.preventDefault(); if (!isDraggingFiles) setIsDraggingFiles(true); }}
                onDragLeave={(e) => { if (e.currentTarget === e.target) setIsDraggingFiles(false); }}
                onDrop={(e) => {
                  e.preventDefault();
                  setIsDraggingFiles(false);
                  if (e.dataTransfer?.files?.length) {
                    const files = Array.from(e.dataTransfer.files);
                    const newTracks: VideoTrack[] = files.filter(f => f.type.startsWith('video/')).map(file => ({
                      type: 'video' as const,
                      id: crypto.randomUUID(),
                      name: file.name,
                      objectUrl: URL.createObjectURL(file),
                      startTime: 0,
                      duration: durationMode === 'custom' ? customDuration : 0.5,
                      fillMode: globalFillMode,
                      bgColor: '#000000',
                      blob: file,
                    }));
                    addTracksToTimeline(newTracks);
                  }
                }}
                className={`group w-full h-full flex flex-col items-center justify-center gap-5 cursor-pointer transition-colors duration-200 bg-zinc-950 ${isDraggingFiles ? 'bg-white/[0.04]' : 'hover:bg-white/[0.02]'}`}
              >
                <div className={`flex flex-col items-center justify-center gap-6 px-12 py-14 rounded-2xl border-2 border-dashed transition-all duration-200 pointer-events-none ${isDraggingFiles ? 'border-white/60 scale-[1.02]' : 'border-[#595959] group-hover:border-[#7a7a7a]'}`}>
                  <div className="w-16 h-16 rounded-2xl bg-white/5 border border-[#595959] flex items-center justify-center">
                    <Film size={28} className="text-white/70" />
                  </div>
                  <div className="flex flex-col items-center gap-3 max-w-sm text-center">
                    <p className="text-[16px] font-medium text-white tracking-[0.1px]">Stitch Clips Together</p>
                    <p className="text-[12px] text-[rgba(218,220,224,0.6)] tracking-[0.1px] leading-relaxed px-2">
                      Import multiple clips to stitch them into a sequence. Use full length or set a uniform duration for every clip, and insert text cards anywhere in your sequence.
                    </p>
                  </div>
                  <div onClick={(e) => e.stopPropagation()} className="w-[180px] pointer-events-auto flex flex-col gap-2">
                    <PillButton variant="solid" icon={<Plus size={16} />} onClick={handleImportFromGallery}>
                      Import
                    </PillButton>
                    <PillButton variant="outline" icon={<Upload size={14} />} onClick={handleUploadFiles}>
                      Upload
                    </PillButton>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="h-56 border-t border-[rgba(218,220,224,0.15)] flex flex-col shrink-0 bg-[#0e0e0e] min-w-0">
          <div className="px-[10px] py-[10px] flex items-center justify-between border-b border-[rgba(218,220,224,0.15)]">
             <div className="w-32 shrink-0 px-2">
               <SectionLabel>Timeline</SectionLabel>
             </div>
             <div className="flex items-center gap-1.5">
               <button onClick={() => insertTextAt(0)} className="h-[30px] px-3 rounded-xl border border-[#595959] hover:border-[#7a7a7a] text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5 active:bg-white/10 flex items-center gap-2 text-[11px] font-medium tracking-[0.1px] transition-colors">
                  <Type size={14} /> Add text
               </button>
               <button onClick={shuffleItems} className="h-[30px] px-3 rounded-xl border border-[#595959] hover:border-[#7a7a7a] text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5 active:bg-white/10 flex items-center gap-2 text-[11px] font-medium tracking-[0.1px] transition-colors">
                  <Shuffle size={14} /> Shuffle
               </button>
             </div>
          </div>

          <div className="flex-1 flex items-center bg-black/20 overflow-hidden min-w-0">
            <div className="w-32 border-r border-[rgba(218,220,224,0.15)] h-full flex flex-col items-center justify-center gap-2 shrink-0 bg-black/10">
              <button 
                onClick={() => { if (!isPlaying) setSequenceIndex(0); setIsPlaying(!isPlaying); }}
                disabled={items.length === 0}
                className={`w-12 h-12 flex items-center justify-center transition-all hover:scale-110 active:scale-95 disabled:opacity-20 ${isPlaying ? 'text-white' : 'text-[rgba(218,220,224,0.55)] hover:text-white'}`}
              >
                {isPlaying ? <Pause size={32} fill="currentColor" /> : <Play size={32} fill="currentColor" className="ml-1" />}
              </button>
            </div>

            <div className="flex-1 overflow-x-auto overflow-y-hidden flex items-center px-6 py-6 h-full dark-scrollbar min-w-0">
              {items.length > 0 ? (
                <>
                  {items.flatMap((item, i) => {
                    const isDragging = draggedIndex !== null;
                    const isInsertActive = i === activeInsertZone;
                    const insertZone = (
                      <div key={`insert-${i}`} className={`group/insert flex-shrink-0 flex items-center justify-center w-4 ${isDragging ? '' : 'hover:w-14'} transition-all duration-200 h-32 relative mx-0`} onClick={() => { if (!isDragging) insertTextAt(i); }} onDragOver={(e) => handleDragOverInsertZone(e, i)} onDrop={() => handleDropAtInsertZone(i)}>
                        <div className={`absolute left-1/2 -translate-x-1/2 transition-all duration-200 ${isInsertActive ? 'w-[4px] h-24 bg-white rounded-full animate-drop-pulse' : 'w-px h-20 bg-white/15'}`} />
                        {!isDragging && (
                          <div className="w-0 group-hover/insert:w-full h-full bg-[#1a1a1a]/0 group-hover/insert:bg-[#1a1a1a] border border-[#595959]/0 group-hover/insert:border-[#595959] flex items-center justify-center rounded-xl transition-all duration-200 shadow-xl overflow-hidden">
                            <Type size={14} className="text-white opacity-0 group-hover/insert:opacity-100 transition-opacity" />
                          </div>
                        )}
                      </div>
                    );

                    const isDragSource = draggedIndex === i;
                    const isLeftAdjacent = activeInsertZone !== -1 && i === activeInsertZone - 1 && !isDragSource;
                    const isRightAdjacent = activeInsertZone !== -1 && i === activeInsertZone && !isDragSource;
                    const isFlanking = isLeftAdjacent || isRightAdjacent;
                    const tileTransform = isDragSource ? 'scale(0.94)' : isFlanking ? `translateX(${isLeftAdjacent ? -8 : 8}px)` : undefined;

                    const tile = (
                      <div 
                        key={item.id} draggable onDragStart={() => handleDragStart(i)} onDragOver={(e) => handleDragOverTile(e, i)} onDrop={() => handleDrop(i)} onDragEnd={handleDragEnd}
                        onClick={() => { setIsPlaying(false); setSelectedIndex(i); }}
                        style={{ transform: tileTransform }}
                        className={`group flex-shrink-0 ${item.type === 'video' ? 'w-32 aspect-square' : 'w-20 h-32'} rounded-xl overflow-hidden border p-1 transition-all duration-200 relative cursor-pointer bg-[#1a1a1a] ${isDragSource ? 'opacity-40' : ''} ${previewIndex === i && !isDragging ? 'border-white scale-[1.02] z-10 shadow-lg' : 'border-[#595959] hover:border-[#7a7a7a]'}`}
                      >
                        {item.type === 'video' ? (
                          <video src={item.objectUrl} className="w-full h-full object-cover rounded-[8px] opacity-60 group-hover:opacity-100" />
                        ) : (
                          <div className="w-full h-full flex flex-col items-center justify-center gap-1">
                            <Type size={18} className={previewIndex === i ? 'text-white' : 'text-[rgba(218,220,224,0.55)]'} />
                            <span className="text-[10px] font-medium text-center truncate w-full px-1">{item.text || 'Text'}</span>
                          </div>
                        )}
                        {selectedIndex === i && !isPlaying && !isDragging && (
                          <button onClick={(e) => { e.stopPropagation(); removeItem(i); }} className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 border border-[#595959] flex items-center justify-center"><X size={12} /></button>
                        )}
                        {isPlaying && sequenceIndex === i && (
                          <div className="absolute bottom-1 left-1 right-1 h-0.5 bg-white/20 rounded-full overflow-hidden">
                            <div className="h-full bg-white animate-progress-clip" style={{ animationDuration: `${item.duration}s` }} />
                          </div>
                        )}
                      </div>
                    );

                    return [insertZone, tile];
                  })}
                  <div key="insert-end" className={`group/insert flex-shrink-0 flex items-center justify-center w-5 ${draggedIndex !== null ? '' : 'hover:w-14'} transition-all duration-200 h-32 relative mx-1`} onClick={() => { if (draggedIndex === null) insertTextAt(items.length); }} onDragOver={(e) => handleDragOverInsertZone(e, items.length)} onDrop={() => handleDropAtInsertZone(items.length)}>
                    <div className={`absolute left-1/2 -translate-x-1/2 transition-all duration-200 ${activeInsertZone === items.length ? 'w-[4px] h-24 bg-white rounded-full animate-drop-pulse' : 'w-px h-20 bg-white/15'}`} />
                    {draggedIndex === null && (
                      <div className="w-0 group-hover/insert:w-full h-full bg-[#1a1a1a]/0 group-hover/insert:bg-[#1a1a1a] border border-[#595959]/0 group-hover/insert:border-[#595959] flex items-center justify-center rounded-xl transition-all duration-200 shadow-xl overflow-hidden">
                        <Type size={14} className="text-white opacity-0 group-hover/insert:opacity-100 transition-opacity" />
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <div className="flex items-center gap-4 opacity-10 select-none">
                  <div className="w-32 aspect-square rounded-xl border border-dashed border-[#595959]" />
                  <div className="w-32 aspect-square rounded-xl border border-dashed border-[#595959]/50" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="w-[300px] shrink-0 border-l border-[rgba(218,220,224,0.15)] flex flex-col overflow-hidden px-[10px] py-[12px] h-full min-h-0 bg-[#0e0e0e]">
        <div className="flex flex-col gap-[16px] items-start w-full flex-1 min-h-0 overflow-y-auto dark-scrollbar pr-1">
          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>Media</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <PillButton variant="solid" icon={<Plus size={16} />} onClick={handleImportFromGallery}>Import</PillButton>
              <PillButton variant="outline" icon={<Upload size={14} />} onClick={handleUploadFiles}>Upload</PillButton>
            </div>
          </div>

          <div className="flex flex-col gap-2 items-start w-full">
             <SectionLabel>Global Settings</SectionLabel>
             <div className="flex flex-col gap-1.5 w-full">
                <FieldDropdown label="Aspect Ratio" value={aspectRatio} options={['9:16', '16:9', '1:1']} onChange={(v) => setAspectRatio(v as AspectRatio)} />
                <div className="mt-1">
                  <SectionLabel>Scaling</SectionLabel>
                  <SegmentedToggle value={globalFillMode} onChange={(v) => setGlobalFillMode(v as FillMode)} items={[{ value: 'fill', label: 'Fill' }, { value: 'fit', label: 'Fit' }]} />
                </div>
                <div className="mt-1">
                  <SectionLabel>Duration</SectionLabel>
                  <SegmentedToggle value={durationMode} onChange={handleDurationModeChange} items={[{ value: 'full', label: 'Full' }, { value: 'custom', label: 'Custom' }]} />
                </div>
                {durationMode === 'custom' && (
                  <RangeSlider label="Duration" value={customDuration} min={0.1} max={effectiveMaxDuration} step={0.1} formatValue={(v) => `${v.toFixed(1)}s`} onChange={updateGlobalDuration} />
                )}
             </div>
          </div>

          {selectedItem?.type === 'text' && selectedIndex !== null && (
            <div className="flex flex-col gap-3 items-start w-full">
              <SectionLabel>Text Style</SectionLabel>
              <div className="w-full px-1">
                <textarea value={selectedItem.text} onChange={(e) => updateItem(selectedIndex, { text: e.target.value })} placeholder="Chapter text..." rows={2} className="w-full bg-transparent border border-[#595959] rounded-xl px-3 py-2 text-[12px] text-white resize-none" />
              </div>
              <div className="flex gap-1.5 w-full px-1">
                <FieldDropdown label="Font" value={selectedItem.fontFamily} options={GOOGLE_FONTS} onChange={(v) => { ensureFontLoaded(v); updateItem(selectedIndex, { fontFamily: v }); }} className="flex-1" />
                <FieldDropdown label="Weight" value={FONT_WEIGHTS.find(w => w.value === selectedItem.fontWeight)?.label || 'Medium'} options={FONT_WEIGHTS.map(w => w.label)} onChange={(v) => {
                  const fw = FONT_WEIGHTS.find(w => w.label === v);
                  if (fw) updateItem(selectedIndex, { fontWeight: fw.value });
                }} className="w-[100px]" />
              </div>
              <RangeSlider label="Size" value={selectedItem.fontSize} min={12} max={200} onChange={(v) => updateItem(selectedIndex, { fontSize: v })} />
              <div className="px-1 w-full"><ColorInput label="Color" value={selectedItem.color} onChange={(v) => updateItem(selectedIndex, { color: v })} /></div>
              <SectionLabel>Position</SectionLabel>
              <div className="w-full px-1"><PositionGrid value={selectedItem.position} onChange={(v) => updateItem(selectedIndex, { position: v })} /></div>
              <RangeSlider label="Text Duration" value={selectedItem.duration} min={0.1} max={10.0} step={0.1} formatValue={(v) => `${v.toFixed(1)}s`} onChange={(v) => updateItem(selectedIndex, { duration: v })} />
            </div>
          )}
        </div>

        <div className="flex flex-col gap-[12px] items-start w-full pt-3 mt-auto shrink-0">
           <PillButton variant="solid" icon={isRendering ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />} onClick={handleRender} disabled={isRendering || items.length === 0}>
             {isRendering ? 'Saving...' : 'Save Stringout'}
           </PillButton>
        </div>
      </div>
    </div>
  );
};

import {
  Input,
  Output,
  BlobSource,
  BufferTarget,
  Mp4OutputFormat,
  ALL_FORMATS,
  EncodedVideoPacketSource,
  EncodedAudioPacketSource,
  EncodedPacketSink,
  EncodedPacket,
  CanvasSink,
  AudioSampleSink,
  VideoSampleSource,
  AudioSampleSource,
  VideoSample,
  AudioSample,
  canEncodeAudio,
} from 'mediabunny';
import { registerAacEncoder } from '@mediabunny/aac-encoder';
import { VideoMetadata, ClipInput, TextItem, TextPosition } from '../types';

// Register AAC encoder if not natively supported
canEncodeAudio('aac').then(supported => {
  if (!supported) {
    registerAacEncoder();
  }
});

/**
 * Extract metadata from a video Blob.
 */
export async function extractMetadata(blob: Blob): Promise<VideoMetadata> {
  const input = new Input({
    formats: ALL_FORMATS,
    source: new BlobSource(blob),
  });

  try {
    const duration = await input.computeDuration();
    const videoTracks = await input.getVideoTracks();
    const audioTracks = await input.getAudioTracks();

    let video: VideoMetadata['video'];
    if (videoTracks.length > 0) {
      const track = videoTracks[0];
      let frameRate = 0;
      try {
        const stats = await track.computePacketStats();
        frameRate = stats.averagePacketRate;
      } catch (e) {
        console.warn("Could not compute video packet stats", e);
      }

      let fullCodec = track.codec || 'unknown';
      try {
        const config = await track.getDecoderConfig();
        if (config && config.codec) {
          fullCodec = config.codec;
        }
      } catch (e) {
        console.warn("Could not get video decoder config", e);
      }

      video = {
        codec: fullCodec,
        width: track.displayWidth,
        height: track.displayHeight,
        frameRate: frameRate,
        rotation: track.rotation,
      };
    }

    let audio: VideoMetadata['audio'];
    if (audioTracks.length > 0) {
      const track = audioTracks[0];

      let fullCodec = track.codec || 'unknown';
      try {
        const config = await track.getDecoderConfig();
        if (config && config.codec) {
          fullCodec = config.codec;
        }
      } catch (e) {
        console.warn("Could not get audio decoder config", e);
      }

      audio = {
        codec: fullCodec,
        sampleRate: track.sampleRate,
        channels: track.numberOfChannels,
      };
    }

    return { duration, video, audio };
  } finally {
    input.dispose();
  }
}

/**
 * Re-encode videos into a uniform format (H.264 High Profile + AAC).
 * Supports per-clip startTime/duration trim and fill/fit modes.
 * targetFPS should be provided to ensure consistent timing across all clips.
 */
export async function reencodeVideos(
  clips: ClipInput[],
  targetWidth: number,
  targetHeight: number,
  targetFPS: number,
  onProgress: (progress: number) => void
): Promise<Blob> {
  if (clips.length === 0) throw new Error("No clips to process");

  const output = new Output({
    format: new Mp4OutputFormat(),
    target: new BufferTarget(),
  });

  // H.264 High Profile for high quality
  const videoSource = new VideoSampleSource({
    codec: 'avc',
    fullCodecString: 'avc1.640028',
    bitrate: 25_000_000, 
  });

  output.addVideoTrack(videoSource, {
    rotation: (clips[0].metadata?.video?.rotation || 0) as any,
    frameRate: targetFPS,
  });

  let hasAnyAudio = false;
  let sampleRate = 48000;
  let channels = 2;

  for (const clip of clips) {
    const meta = clip.metadata ?? await extractMetadata(clip.blob);
    if (meta.audio) { 
      hasAnyAudio = true; 
      sampleRate = meta.audio.sampleRate;
      channels = meta.audio.channels;
      break; 
    }
  }

  let audioSource: AudioSampleSource | null = null;
  if (hasAnyAudio) {
    audioSource = new AudioSampleSource({
      codec: 'aac',
      fullCodecString: 'mp4a.40.2',
      bitrate: 192_000,
    });
    output.addAudioTrack(audioSource);
  }

  await output.start();

  let lastVideoTimestamp = 0;
  let lastAudioTimestamp = 0;
  let processedClips = 0;

  for (const clip of clips) {
    const input = new Input({
      formats: ALL_FORMATS,
      source: new BlobSource(clip.blob),
    });

    let nextVideo: any = null;
    let nextAudio: any = null;

    try {
      const videoTracks = await input.getVideoTracks();
      const audioTracks = await input.getAudioTracks();

      const videoTrack = videoTracks[0];
      const audioTrack = audioTracks[0];

      let videoIterator: AsyncIterator<any> | null = null;
      let audioIterator: AsyncIterator<any> | null = null;

      if (videoTrack) {
        const fitMode = clip.fillMode === 'fill' ? 'cover' : 'contain';
        const canvasSink = new CanvasSink(videoTrack, {
          width: targetWidth,
          height: targetHeight,
          fit: fitMode as any,
        });
        videoIterator = canvasSink.canvases()[Symbol.asyncIterator]();
      }

      if (audioTrack && audioSource) {
        const audioSink = new AudioSampleSink(audioTrack);
        audioIterator = audioSink.samples()[Symbol.asyncIterator]();
      }

      nextVideo = videoIterator ? await videoIterator.next() : { done: true, value: null };
      nextAudio = audioIterator ? await audioIterator.next() : { done: true, value: null };

      let firstVideoTsInClip: number | null = null;
      let firstAudioTsInClip: number | null = null;

      let maxVideoTsInClip = 0;
      let maxAudioTsInClip = 0;

      const clipStart = clip.startTime;
      const clipEnd = clip.startTime + clip.duration;

      // Handle audio-less clips (like text cards) when the output has audio.
      // We need to insert silence to maintain sync.
      if (audioSource && !audioTrack) {
        // Generate silence for the duration of this clip
        const silenceDuration = clip.duration;
        const silenceSamplesCount = Math.floor(sampleRate * silenceDuration);
        const buffer = new Float32Array(silenceSamplesCount * channels);
        // buffer is already silent (0s)

        const audioData = new AudioData({
          format: 'f32',
          sampleRate: sampleRate,
          numberOfFrames: silenceSamplesCount,
          numberOfChannels: channels,
          timestamp: lastAudioTimestamp * 1000000, // microsec
          data: buffer,
        });

        const silenceSample = new AudioSample(audioData);
        try {
          await audioSource.add(silenceSample);
        } finally {
          silenceSample.close();
        }
        maxAudioTsInClip = silenceDuration;
      }

      while (!nextVideo.done || !nextAudio.done) {
        const videoTs = !nextVideo.done ? nextVideo.value.timestamp : Infinity;
        const audioTs = !nextAudio.done ? nextAudio.value.timestamp : Infinity;

        const useVideo = videoTs <= audioTs;

        if (useVideo) {
          const canvasData = nextVideo.value;
          if (!canvasData) {
            nextVideo = await videoIterator!.next();
            continue;
          }
          try {
            if (firstVideoTsInClip === null) firstVideoTsInClip = canvasData.timestamp;
            const normalizedTs = canvasData.timestamp - firstVideoTsInClip;

            if (normalizedTs >= clipStart && normalizedTs < clipEnd) {
              const trimmedTs = normalizedTs - clipStart;
              const newTimestamp = lastVideoTimestamp + trimmedTs;
              const frameDuration = canvasData.duration || (1 / targetFPS);

              const sample = new VideoSample(canvasData.canvas, {
                timestamp: newTimestamp,
                duration: frameDuration,
              });

              try {
                await videoSource.add(sample);
              } finally {
                sample.close();
              }
              maxVideoTsInClip = Math.max(maxVideoTsInClip, trimmedTs + frameDuration);
            }
          } finally {
            if (typeof canvasData.close === 'function') {
              canvasData.close();
            } else if (canvasData.canvas && typeof canvasData.canvas.close === 'function') {
              canvasData.canvas.close();
            }
          }

          if (firstVideoTsInClip !== null && (canvasData.timestamp - firstVideoTsInClip) >= clipEnd) {
            nextVideo = { done: true, value: null };
          } else {
            nextVideo = await videoIterator!.next();
          }
        } else {
          const audioSample = nextAudio.value;
          if (!audioSample) {
            nextAudio = await audioIterator!.next();
            continue;
          }
          try {
            if (firstAudioTsInClip === null) firstAudioTsInClip = audioSample.timestamp;
            const normalizedTs = audioSample.timestamp - firstAudioTsInClip;

            if (normalizedTs >= clipStart && normalizedTs < clipEnd) {
              const trimmedTs = normalizedTs - clipStart;
              const newTimestamp = lastAudioTimestamp + trimmedTs;

              const clonedSample = audioSample.clone();
              try {
                clonedSample.setTimestamp(newTimestamp);
                await audioSource!.add(clonedSample);
              } finally {
                clonedSample.close();
              }
              maxAudioTsInClip = Math.max(maxAudioTsInClip, trimmedTs + audioSample.duration);
            }
          } finally {
            if (typeof audioSample.close === 'function') {
              audioSample.close();
            }
          }

          if (firstAudioTsInClip !== null && (audioSample.timestamp - firstAudioTsInClip) >= clipEnd) {
            nextAudio = { done: true, value: null };
          } else {
            nextAudio = await audioIterator!.next();
          }
        }
      }

      const clipDuration = Math.max(maxVideoTsInClip, maxAudioTsInClip, clip.duration);
      lastVideoTimestamp += clipDuration;
      lastAudioTimestamp += clipDuration;

      processedClips++;
      onProgress(processedClips / clips.length);
    } finally {
      input.dispose();
    }
  }

  videoSource.close();
  audioSource?.close();
  await output.finalize();

  const buffer = (output as any).target.buffer;
  if (!buffer) throw new Error("Output buffer is empty");

  return new Blob([buffer], { type: 'video/mp4' });
}

/**
 * Stream-copy concatenation (fast path).
 * Only used when all clips share identical parameters.
 */
export async function concatenateVideos(
  clips: ClipInput[],
  onProgress: (progress: number) => void
): Promise<Blob> {
  if (clips.length === 0) throw new Error("No clips to concatenate");

  const firstMetadata = clips[0].metadata ?? await extractMetadata(clips[0].blob);
  if (!firstMetadata.video) throw new Error("First clip has no video track");

  let audioReferenceMeta: VideoMetadata | undefined = firstMetadata.audio ? firstMetadata : undefined;
  if (!audioReferenceMeta) {
    for (const clip of clips) {
      const m = clip.metadata ?? await extractMetadata(clip.blob);
      if (m.audio) { audioReferenceMeta = m; break; }
    }
  }

  const output = new Output({
    format: new Mp4OutputFormat(),
    target: new BufferTarget(),
  });

  const videoCodec = firstMetadata.video.codec.startsWith('avc1') ? 'avc' :
                     (firstMetadata.video.codec.startsWith('hev1') || firstMetadata.video.codec.startsWith('hvc1')) ? 'hevc' :
                     firstMetadata.video.codec.startsWith('vp09') ? 'vp9' :
                     firstMetadata.video.codec.startsWith('av01') ? 'av1' :
                     firstMetadata.video.codec.startsWith('vp8') ? 'vp8' :
                     firstMetadata.video.codec;

  const videoSource = new EncodedVideoPacketSource(videoCodec as any);

  const finalFrameRate = firstMetadata.video.frameRate || 30;
  output.addVideoTrack(videoSource, {
    rotation: (firstMetadata.video.rotation || 0) as any,
    frameRate: finalFrameRate,
  });

  let audioSource: EncodedAudioPacketSource | null = null;
  if (audioReferenceMeta?.audio) {
    const audioCodec = audioReferenceMeta.audio.codec.startsWith('mp4a') ? 'aac' : audioReferenceMeta.audio.codec;
    audioSource = new EncodedAudioPacketSource(audioCodec as any);
    output.addAudioTrack(audioSource);
  }

  await output.start();

  let lastVideoTimestamp = 0;
  let lastAudioTimestamp = 0;
  let videoSequenceNumber = 0;
  let audioSequenceNumber = 0;
  let processedClips = 0;

  for (const clip of clips) {
    const input = new Input({
      formats: ALL_FORMATS,
      source: new BlobSource(clip.blob),
    });

    const clipStart = clip.startTime;
    const clipEnd = clip.startTime + clip.duration;

    try {
      const videoTracks = await input.getVideoTracks();
      const audioTracks = await input.getAudioTracks();

      const videoTrack = videoTracks[0];
      const audioTrack = audioTracks[0];

      const videoPackets = videoTrack ? new EncodedPacketSink(videoTrack).packets()[Symbol.asyncIterator]() : null;
      const audioPackets = audioTrack ? new EncodedPacketSink(audioTrack).packets()[Symbol.asyncIterator]() : null;

      const videoDecoderConfig = videoTrack ? await videoTrack.getDecoderConfig() : null;
      const audioDecoderConfig = audioTrack ? await audioTrack.getDecoderConfig() : null;

      let nextVideo = videoPackets ? await videoPackets.next() : { done: true, value: null as any };
      let nextAudio = audioPackets ? await audioPackets.next() : { done: true, value: null as any };

      let isVeryFirstVideoPacketInThisClip = true;
      let isVeryFirstAudioPacketInThisClip = true;

      let videoClipOffset: number | null = null;
      let audioClipOffset: number | null = null;

      let firstVideoTsInClip: number | null = null;
      let firstAudioTsInClip: number | null = null;

      let hasSeenVideoKeyframe = false;

      while (!nextVideo.done || !nextAudio.done) {
        if (!hasSeenVideoKeyframe && !nextVideo.done) {
          if (firstVideoTsInClip === null) firstVideoTsInClip = nextVideo.value.timestamp;
          const normalizedTs = nextVideo.value.timestamp - firstVideoTsInClip;

          if (nextVideo.value.type === 'key' && normalizedTs >= clipStart) {
            hasSeenVideoKeyframe = true;
            videoClipOffset = lastVideoTimestamp - nextVideo.value.timestamp;
          } else {
            nextVideo = await videoPackets!.next();
            continue;
          }
        }

        if (!nextAudio.done && firstAudioTsInClip === null) {
          firstAudioTsInClip = nextAudio.value.timestamp;
        }
        if (!nextAudio.done && audioClipOffset === null && firstAudioTsInClip !== null) {
          const normalizedTs = nextAudio.value.timestamp - firstAudioTsInClip;
          if (normalizedTs >= clipStart) {
            audioClipOffset = lastAudioTimestamp - nextAudio.value.timestamp;
          } else {
            nextAudio = await audioPackets!.next();
            continue;
          }
        }

        const nextVideoTs = !nextVideo.done && videoClipOffset !== null ? nextVideo.value.timestamp + videoClipOffset : Infinity;
        const nextAudioTs = !nextAudio.done && audioClipOffset !== null ? nextAudio.value.timestamp + audioClipOffset : Infinity;

        const useVideo = nextVideoTs <= nextAudioTs;

        if (useVideo && !nextVideo.done) {
          const packet = nextVideo.value;
          const normalizedTs = packet.timestamp - firstVideoTsInClip!;

          if (normalizedTs >= clipEnd) {
            nextVideo = { done: true, value: null as any };
            continue;
          }

          const newTimestamp = packet.timestamp + videoClipOffset!;
          const frameDuration = packet.duration || (1 / (firstMetadata.video?.frameRate || 30));

          const newPacket = new EncodedPacket(
            packet.data,
            packet.type,
            newTimestamp,
            frameDuration,
            videoSequenceNumber++,
            packet.byteLength,
            packet.sideData
          );

          if ((packet as any).compositionOffset !== undefined) {
            (newPacket as any).compositionOffset = (packet as any).compositionOffset;
          }

          await videoSource.add(newPacket, isVeryFirstVideoPacketInThisClip ? { decoderConfig: videoDecoderConfig || undefined } : undefined);
          isVeryFirstVideoPacketInThisClip = false;
          lastVideoTimestamp = Math.max(lastVideoTimestamp, newTimestamp + frameDuration);
          nextVideo = await videoPackets!.next();
        } else if (!nextAudio.done && audioClipOffset !== null) {
          const packet = nextAudio.value;
          const normalizedTs = packet.timestamp - firstAudioTsInClip!;

          if (normalizedTs >= clipEnd) {
            nextAudio = { done: true, value: null as any };
            continue;
          }

          if (audioSource) {
            const newTimestamp = packet.timestamp + audioClipOffset;
            const audioDuration = packet.duration || 0.02;

            const newPacket = new EncodedPacket(
              packet.data,
              packet.type,
              newTimestamp,
              audioDuration,
              audioSequenceNumber++,
              packet.byteLength,
              packet.sideData
            );

            await audioSource.add(newPacket, isVeryFirstAudioPacketInThisClip ? { decoderConfig: audioDecoderConfig || undefined } : undefined);
            isVeryFirstAudioPacketInThisClip = false;
            lastAudioTimestamp = Math.max(lastAudioTimestamp, newTimestamp + audioDuration);
          }

          nextAudio = await audioPackets!.next();
        } else {
          if (!nextVideo.done) nextVideo = await videoPackets!.next();
          if (!nextAudio.done) nextAudio = await audioPackets!.next();
        }
      }

      const maxClipTimestamp = Math.max(lastVideoTimestamp, lastAudioTimestamp, lastVideoTimestamp + clip.duration);
      lastVideoTimestamp = maxClipTimestamp;
      lastAudioTimestamp = maxClipTimestamp;

      processedClips++;
      onProgress(processedClips / clips.length);
    } finally {
      input.dispose();
    }
  }

  videoSource.close();
  audioSource?.close();
  await output.finalize();

  const buffer = (output as any).target.buffer;
  if (!buffer) throw new Error("Concatenation buffer is empty");

  return new Blob([buffer], { type: 'video/mp4' });
}

/**
 * Generate a short MP4 video blob from a TextItem using H.264 High Profile.
 * targetFPS ensures the card matches the rest of the stringout for smoothness.
 */
export async function generateTextBlob(
  textItem: TextItem,
  targetWidth: number,
  targetHeight: number,
  targetFPS: number
): Promise<Blob> {
  const totalFrames = Math.max(1, Math.ceil(textItem.duration * targetFPS));

  const canvas = new OffscreenCanvas(targetWidth, targetHeight);
  const ctx = canvas.getContext('2d')!;

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, targetWidth, targetHeight);

  ctx.fillStyle = textItem.color;
  ctx.font = `${textItem.fontWeight} ${textItem.fontSize}px "${textItem.fontFamily}", sans-serif`;
  ctx.textBaseline = 'middle';

  const padding = targetWidth * 0.08;
  let x: number;
  let y: number;

  const pos = textItem.position;
  if (pos.includes('left')) {
    ctx.textAlign = 'left';
    x = padding;
  } else if (pos.includes('right')) {
    ctx.textAlign = 'right';
    x = targetWidth - padding;
  } else {
    ctx.textAlign = 'center';
    x = targetWidth / 2;
  }

  if (pos.startsWith('top')) {
    y = targetHeight * 0.15;
  } else if (pos.startsWith('bottom')) {
    y = targetHeight * 0.85;
  } else {
    y = targetHeight / 2;
  }

  const maxWidth = targetWidth - padding * 2;
  const lines = wrapText(ctx, textItem.text || ' ', maxWidth);
  const lineHeightPx = textItem.fontSize * 1.2;
  const totalTextHeight = lines.length * lineHeightPx;
  const startY = y - totalTextHeight / 2 + lineHeightPx / 2;

  for (let li = 0; li < lines.length; li++) {
    ctx.fillText(lines[li], x, startY + li * lineHeightPx);
  }

  const output = new Output({
    format: new Mp4OutputFormat(),
    target: new BufferTarget(),
  });

  // Using H.264 High Profile and 10Mbps for text cards
  const videoSource = new VideoSampleSource({
    codec: 'avc',
    fullCodecString: 'avc1.640028',
    bitrate: 10_000_000,
  });

  output.addVideoTrack(videoSource, {
    rotation: 0 as any,
    frameRate: targetFPS,
  });

  await output.start();

  for (let i = 0; i < totalFrames; i++) {
    const timestamp = i / targetFPS;
    const frameDuration = 1 / targetFPS;

    const sample = new VideoSample(canvas, {
      timestamp,
      duration: frameDuration,
    });

    try {
      await videoSource.add(sample);
    } finally {
      sample.close();
    }
  }

  videoSource.close();
  await output.finalize();

  const textBuffer = (output as any).target.buffer;
  if (!textBuffer) throw new Error("Text video buffer is empty");

  return new Blob([textBuffer], { type: 'video/mp4' });
}

function wrapText(ctx: OffscreenCanvasRenderingContext2D, text: string, maxWidth: number): string[] {
  const paragraphs = text.split('\n');
  const lines: string[] = [];

  for (const paragraph of paragraphs) {
    const words = paragraph.split(' ');
    let currentLine = '';

    for (const word of words) {
      const testLine = currentLine ? `${currentLine} ${word}` : word;
      const metrics = ctx.measureText(testLine);
      if (metrics.width > maxWidth && currentLine) {
        lines.push(currentLine);
        currentLine = word;
      } else {
        currentLine = testLine;
      }
    }
    if (currentLine) lines.push(currentLine);
  }

  return lines.length > 0 ? lines : [' '];
}

